def main():
    target = sys.argv[1] if len(sys.argv) > 1 else "StudentPlanner"
    if os.path.exists(target) and os.listdir(target):
        print("The folder '%s' already exists and is not empty. Rename it or pass another name:" % target)
        print("    python StudentPlanner_all_in_one.py NewFolderName")
        return 1
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(DATA))) as z:
        for member in z.namelist():
            name = member[2:] if member.startswith("./") else member
            if name.startswith("StudentPlanner/"):
                name = name[len("StudentPlanner/"):]
            if not name:
                continue
            out = os.path.realpath(os.path.join(target, name))
            if not out.startswith(os.path.realpath(target) + os.sep):
                continue
            if name.endswith("/"):
                os.makedirs(out, exist_ok=True)
                continue
            os.makedirs(os.path.dirname(out), exist_ok=True)
            with open(out, "wb") as f:
                f.write(z.read(member))
    print("Created the folder '%s'. Next:" % target)
    print("    cd %s" % target)
    print("    python server.py")
    return 0

if __name__ == "__main__":
    sys.exit(main())
